<div class="flex min-h-[620px] items-center justify-center bg-muted/20 p-6 md:p-10">
    <april:card class="w-full max-w-lg"><slot:title>Join a workspace</slot:title><slot:description>Enter the invite details from your team.</slot:description><slot:content class="space-y-5"><div class="space-y-2"><april:label for="signup-05-code">Invitation code</april:label><april:input id="signup-05-code" placeholder="NORTHSTAR-2026" class="w-full" /></div><div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><april:label for="signup-05-name">Your name</april:label><april:input id="signup-05-name" /></div><div class="space-y-2"><april:label for="signup-05-role">Role</april:label><april:select id="signup-05-role"><option>Designer</option><option>Developer</option><option>Manager</option></april:select></div></div><div class="flex items-start gap-2"><april:checkbox id="signup-05-updates" /><april:label for="signup-05-updates" class="text-sm font-normal leading-5">Send me occasional product updates.</april:label></div><april:button type="button" class="w-full">Join workspace</april:button></slot:content></april:card>
</div>
